// Buat variabel 'WarnaSaat' dan 'UkuranSaat'

// --- Sprite TOMBOL MERAH ---
[ketika sprite ini diklik]
[atur [WarnaSaat ▼] ke [0]]  // 0 = merah di sistem warna Pen

// --- Sprite TOMBOL BIRU ---
[ketika sprite ini diklik]
[atur [WarnaSaat ▼] ke [60]]  // 60 = biru

// --- Sprite TOMBOL HIJAU ---
[ketika sprite ini diklik]
[atur [WarnaSaat ▼] ke [40]]  // 40 = hijau

// --- Di sprite KUAS: terapkan warna ---
[ketika bendera hijau diklik]
// Tambahkan di dalam loop:
[atur warna pena ke (WarnaSaat)]
